/**  A game's executable. */
"malaf_tanfidhi" | 
/**  A launcher's installation folder. */
"mujallad_manassa" | 
/**  Where Taarib keeps downloaded patches. */
"mujallad_ruqaa" | 
/**  A font file. */
"malaf_khatt" | 
/**  A patch file to import. */
"malaf_ruqaa";

/**  Which of the three routes a game takes, decided before anything runs. */
